// Storage pre-failure watch.
//
// This deliberately does not duplicate health-monitor, which already reports
// zfs_pool_health and smart_status once a day. Those two are pass/fail and
// stay "pass" until the moment they do not -- SMART's whole failure mode is
// that it says PASSED right up to the end. What this looks at instead is the
// numbers that move first: wear, spare blocks, reallocated and pending
// sectors, media errors, and the rate the wear indicator is climbing at.
//
// It sends nothing itself. Everything goes to the alert spine, which owns
// suppression, so a drive that has been dying for a month does not send a
// notification every six hours.

const PROM = "http://127.0.0.1:8451/api/v1/query";
const SOURCE = "disk-health";

// Tiers, not a single threshold: crossing 80% is worth one push, and a drive
// sitting at 81% for a month is worth none. The spine cannot know that, so
// wear is the one check here that tracks its own state.
const WEAR_TIERS = [75, 80, 85, 90, 95, 100];
const PROJECTION_CRITICAL_DAYS = 30;
const PROJECTION_WARNING_DAYS = 90;

// Drive temperature limits differ by kind, and the exporter only reports a
// rotation rate for spinning disks, so that is how a device is classified.
const TEMP_LIMITS = { hdd: { warning: 55, critical: 60 }, ssd: { warning: 70, critical: 80 } };

const query = `
label_replace(zfs_pool_health, "metric", "zfs_health", "", "")
or label_replace(smartctl_device_smart_status, "metric", "smart_status", "", "")
or label_replace(smartctl_device_critical_warning, "metric", "nvme_critical", "", "")
or label_replace(smartctl_device_available_spare, "metric", "nvme_spare", "", "")
or label_replace(smartctl_device_available_spare_threshold, "metric", "nvme_spare_floor", "", "")
or label_replace(smartctl_device_percentage_used, "metric", "wear_pct", "", "")
or label_replace(deriv(smartctl_device_percentage_used[7d]) * 86400, "metric", "wear_per_day", "", "")
or label_replace(smartctl_device_media_errors, "metric", "media_errors", "", "")
or label_replace(smartctl_device_temperature, "metric", "temperature", "", "")
or label_replace(smartctl_device_rotation_rate, "metric", "rotation", "", "")
or label_replace(smartctl_device_smartctl_exit_status, "metric", "exit_status", "", "")
or label_replace(smartctl_device_attribute{attribute_value_type="raw", attribute_name=~"Current_Pending_Sector|Offline_Uncorrectable|Reallocated_Sector_Ct|UDMA_CRC_Error_Count"}, "metric", "ata", "", "")
`;

let series;
try {
  const response = await this.helpers.httpRequest({ method: "GET", url: PROM, qs: { query }, json: true });
  series = response?.data?.result ?? [];
} catch (error) {
  // Prometheus being unreachable is itself a storage-adjacent problem worth
  // one warning, and returning silently would look identical to "all drives
  // healthy" -- which is the failure mode this whole workflow exists to avoid.
  return [
    {
      json: {
        source: SOURCE,
        severity: "warning",
        title: "cannot read drive metrics",
        message: `Prometheus at ${PROM} did not answer, so no drive was checked this run.\n\n${error.message}`,
        fingerprint: `${SOURCE}:prometheus-unreachable`,
      },
    },
  ];
}

const pick = (name) => series.filter((s) => s.metric.metric === name);
const num = (s) => Number(s.value[1]);
const first = (name, device) => pick(name).find((s) => s.metric.device === device);
const devices = [...new Set(pick("smart_status").map((s) => s.metric.device))].sort();

const state = $getWorkflowStaticData("global");
if (!state.wearTier) state.wearTier = {};

const alerts = [];
// `resolved` is emitted for every binary check that currently passes. The
// spine drops resolutions for alerts it never sent, so this closes out a
// recovered drive without this workflow having to remember what it sent.
const report = (severity, title, message, fingerprint, resolved = false) =>
  alerts.push({ json: { source: SOURCE, severity, title, message, fingerprint, resolved } });

// {{{ Pools
for (const s of pick("zfs_health")) {
  const pool = s.metric.pool;
  const healthy = num(s) === 0;
  report(
    "critical",
    `zpool ${pool} is not ONLINE`,
    `zfs_pool_health reports ${num(s)} for ${pool}. Run \`zpool status -v ${pool}\`; a degraded pool still serves reads, so nothing else will look wrong.`,
    `${SOURCE}:zpool:${pool}`,
    healthy,
  );
}
// }}}

for (const device of devices) {
  const rotation = first("rotation", device);
  const kind = rotation && num(rotation) > 0 ? "hdd" : "ssd";
  const label = `${device} (${kind === "hdd" ? "spinning" : "solid state"})`;

  // {{{ Overall SMART verdict
  const smart = first("smart_status", device);
  if (smart) {
    report(
      "critical",
      `SMART on ${device} reports FAILING`,
      `The drive's own overall-health self-assessment has flipped. Replace ${label} now and do not wait for a scrub.`,
      `${SOURCE}:smart:${device}`,
      num(smart) === 1,
    );
  }

  const exit = first("exit_status", device);
  if (exit) {
    report(
      "warning",
      `cannot read SMART data from ${device}`,
      `smartctl exited ${num(exit)} for ${label}, so this drive is unmonitored rather than healthy.`,
      `${SOURCE}:smartctl-exit:${device}`,
      num(exit) === 0,
    );
  }
  // }}}

  // {{{ Wear, and how fast it is moving
  const wear = first("wear_pct", device);
  if (wear) {
    const pct = num(wear);
    const perDayRaw = first("wear_per_day", device);
    const perDay = perDayRaw ? num(perDayRaw) : 0;
    const daysLeft = perDay > 0 ? Math.round((100 - pct) / perDay) : null;

    const trend =
      daysLeft === null
        ? "Not enough history to project a trend."
        : `Climbing ${perDay.toFixed(2)} points/day, which reaches 100% in about ${daysLeft} days.`;
    const caveat =
      "100% is the manufacturer's wear estimate, not a cliff -- drives usually keep going past it, but it is the point after which endurance is no longer specified.";

    const tier = WEAR_TIERS.filter((t) => pct >= t).pop() ?? null;
    if (tier !== null && tier > (state.wearTier[device] ?? 0)) {
      state.wearTier[device] = tier;
      report(
        tier >= 95 ? "critical" : tier >= 85 ? "warning" : "info",
        `${device} wear crossed ${tier}%`,
        `${label} reports ${pct}% of rated write endurance used.\n\n${trend}\n\n${caveat}`,
        `${SOURCE}:wear-tier:${device}:${tier}`,
      );
    }

    // The projection repeats where the tier crossing does not: running out of
    // drive inside a month is worth being reminded about.
    if (daysLeft !== null && daysLeft < PROJECTION_WARNING_DAYS) {
      report(
        daysLeft < PROJECTION_CRITICAL_DAYS ? "critical" : "warning",
        `${device} projected to exhaust endurance in ${daysLeft} days`,
        `${label} is at ${pct}% wear. ${trend}\n\nOrder a replacement.\n\n${caveat}`,
        `${SOURCE}:wear-projection:${device}`,
      );
    }
  }
  // }}}

  // {{{ NVMe specifics
  const critical = first("nvme_critical", device);
  if (critical) {
    report(
      "critical",
      `${device} raised an NVMe critical warning`,
      `critical_warning = ${num(critical)}. The bits mean, in order: spare below threshold, temperature out of range, reliability degraded, media in read-only, volatile memory backup failed.`,
      `${SOURCE}:nvme-critical:${device}`,
      num(critical) === 0,
    );
  }

  const spare = first("nvme_spare", device);
  const floor = first("nvme_spare_floor", device);
  if (spare && floor) {
    report(
      "critical",
      `${device} is out of spare blocks`,
      `Available spare ${num(spare)}% has reached the drive's own floor of ${num(floor)}%. Remapping is what hides bad flash; past this point failures surface as read errors.`,
      `${SOURCE}:nvme-spare:${device}`,
      num(spare) > num(floor),
    );
  }

  const media = first("media_errors", device);
  if (media) {
    report(
      "warning",
      `${device} reports ${num(media)} media errors`,
      `Uncorrectable data-integrity errors on ${label}. On a pool with redundancy ZFS will have repaired the data; on ${device} it is still a reason to look.`,
      `${SOURCE}:media-errors:${device}`,
      num(media) === 0,
    );
  }
  // }}}

  // {{{ Temperature
  const temp = first("temperature", device);
  if (temp) {
    const limits = TEMP_LIMITS[kind];
    const value = num(temp);
    report(
      value >= limits.critical ? "critical" : "warning",
      `${device} is running at ${value}°C`,
      `Above the ${kind === "hdd" ? "spinning-disk" : "solid-state"} limit of ${limits.warning}°C. Sustained heat is the one wear factor that is cheap to fix -- check airflow before replacing anything.`,
      `${SOURCE}:temperature:${device}`,
      value < limits.warning,
    );
  }
  // }}}
}

// {{{ ATA surface defects
// Reallocated sectors are history and only interesting when they grow;
// pending and offline-uncorrectable sectors are live surface damage and mean
// the drive could not read data it was asked for.
const ATA_RULES = {
  Current_Pending_Sector: { severity: "critical", note: "Sectors the drive could not read and has not yet remapped. This is unreadable data right now." },
  Offline_Uncorrectable: { severity: "critical", note: "Sectors that failed a background scan and could not be recovered." },
  Reallocated_Sector_Ct: { severity: "warning", note: "Sectors already remapped to spares. A non-zero count that keeps growing is a drive on the way out." },
  UDMA_CRC_Error_Count: { severity: "warning", note: "Transfer errors on the cable, not the platter. Reseat the SATA cable before suspecting the drive." },
};

for (const s of pick("ata")) {
  const { device, attribute_name: attribute } = s.metric;
  const rule = ATA_RULES[attribute];
  if (!rule) continue;
  const count = num(s);
  report(
    rule.severity,
    `${device}: ${attribute} = ${count}`,
    rule.note,
    `${SOURCE}:ata:${device}:${attribute}`,
    count === 0,
  );
}
// }}}

return alerts;
